            position: sticky;
            top: 0;
            z-index: 1000;
        }

        .nav-container {
            max-width: 1200px;
            margin: 0 auto;
            padding: 0 var(--spacing);
            display: flex;
            justify-content: space-between;
            align-items: center;
            height: 70px;
        }

        .logo {
            font-size: 24px;
            font-weight: bold;
            color: var(--primary-color);
            display: flex;
            align-items: center;
            gap: 10px;
        }

        .logo span {
            color: var(--text-color);
        }

        nav ul {
            display: flex;
            gap: 30px;
        }

        nav a {
            font-size: 16px;
            font-weight: 500;
        }

        nav a:hover, nav a.active {
            color: var(--primary-color);
        }

        .cta-button {
            background-color: var(--primary-color);
            color: white;
            padding: 10px 20px;
            border-radius: var(--border-radius);
            font-weight: bold;
            transition: background 0.3s;
        }

        .cta-button:hover {
            background-color: var(--secondary-color);
            color: white;
        }

        /* Hero Section */
        .hero {
            background: linear-gradient(rgba(0, 0, 0, 0.5), rgba(0, 0, 0, 0.5)), url('https://picsum.photos/seed/cleanhome/1440/600');
            background-size: cover;
            background-position: center;
            height: 500px;
            display: flex;
            align-items: center;
            justify-content: center;
            text-align: center;
            color: white;
        }

        .hero-content h1 {
            font-size: 48px;
            margin-bottom: 20px;
        }

        .hero-content p {
            font-size: 20px;
            margin-bottom: 30px;
            opacity: 0.9;
        }

        /* Features */
        .features {
            padding: 60px var(--spacing);
            background-color: var(--bg-light);
        }

        .features-grid {
            max-width: 1200px;
            margin: 0 auto;
            display: grid;
            grid-template-columns: repeat(auto-fit, minmax(250px, 1fr));
            gap: 30px;
        }

        .feature-card {
            background: white;
            padding: 30px;
            border-radius: var(--border-radius);
            box-shadow: 0 4px 6px rgba(0,0,0,0.05);
            text-align: center;
            transition: transform 0.3s;
        }

        .feature-card:hover {
            transform: translateY(-5px);
        }

        .feature-icon {
            font-size: 40px;
            margin-bottom: 15px;
            color: var(--primary-color);
        }

        /* Testimonial */
        .testimonial {
            padding: 60px var(--spacing);
            text-align: center;
        }

        .testimonial p {
            font-size: 18px;
            font-style: italic;
            max-width: 800px;
            margin: 0 auto 20px;
        }

        .testimonial span {
            display: block;
            font-weight: bold;
            color: var(--primary-color);
        }

