            background-color: var(--primary-color);
            color: white;
            padding: 60px var(--spacing);
            text-align: center;
        }

        .cta-section h2 {
            margin-bottom: 20px;
        }

        /* Footer */
        footer {
            background-color: #222;
            color: #ccc;
            padding: 40px var(--spacing);
            text-align: center;
        }

        footer p {
            margin-bottom: 10px;
        }

        /* Responsive */
        @media (max-width: 768px) {
            .nav-container {
                flex-direction: column;
                height: auto;
                padding: 15px;
            }
            nav ul {
                margin-top: 15px;
                flex-wrap: wrap;
                justify-content: center;
                gap: 15px;
            }
            .hero-content h1 {
